import{bV as o,aL as t,u as d,G as c}from"./chunks/framework.DvBUyM1S.js";const u=JSON.parse('{"title":"Git分支开发模型规范","description":"","frontmatter":{"title":"Git分支开发模型规范","date":"2022-05-10T11:32:30.000Z","categories":[null],"tags":["Git"],"author":"七寸知架构","link":"https://www.jianshu.com/p/cbd8cf5e232d","permalink":"/pages/c5d2f8/"},"headers":[],"relativePath":"06.工具/02.Git/04.Git分支开发模型规范.md","filePath":"06.工具/02.Git/04.Git分支开发模型规范.md","lastUpdated":1652201761000}'),r={name:"06.工具/02.Git/04.Git分支开发模型规范.md"};function a(s,e,n,l,i,g){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="git分支开发模型规范" tabindex="-1">Git分支开发模型规范 <a class="header-anchor" href="#git分支开发模型规范" aria-label="Permalink to &quot;Git分支开发模型规范&quot;">​</a></h1><p><img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20220510-16501064376344.webp" alt="Git分支开发模型" loading="lazy"></p><ol><li><strong>最稳定的代码放在 <code>master</code> 分支上（相当于 SVN 的 trunk 分支）</strong>，我们不要直接在 <code>master</code> 分支上提交代码，<strong>只能在该分支上进行代码合并操作</strong>，例如将其它分支的代码合并到 <code>master</code> 分支上。</li><li>我们日常开发中的 <strong>代码需要从 <code>master</code> 分支拉一条 <code>develop</code> 分支出来，该分支所有人都能访问</strong>，但一般情况下，我们也不会直接在该分支上提交代码，代码同样是从其它分支合并到 <code>develop</code> 分支上去。</li><li>当我们需要开发某个特性时，需要 <strong>从 <code>develop</code> 分支拉出一条 <code>feature</code> 分支</strong>，例如 <code>feature-name1</code> 与 <code>feature-name2</code>，在这些分支上并行地开发具体特性。</li><li>当特性开发完毕后，<strong>我们决定需要发布某个版本了，此时需要从 <code>develop</code> 分支上拉出一条 <code>qa</code> 分支</strong>，例如 <code>qa-name1-name2</code>，并将需要发布的特性从相关 <code>feature</code> 分支一同合并到 <code>qa</code> 分支上，随后将针对 <code>qa</code> 分支部署测试环境，<strong><code>测试工程师在该分支上做功能测试，开发工程师在该分支上修改 bug</code></strong>。</li><li><strong>待测试工程师无法找到任何 bug 时</strong>，我们可继续从 <code>master</code> 分支拉出一条 <code>release</code> 分支，<strong><code>此时release的版本号必须根据master的tag版本号来递增，递增规则参见下面版本号规范</code></strong>，例如 <code>release1.0.0</code>，并将<code>qa-name1-name2</code>分支合并到<code>release1.0.0</code>，并部署到预发环境，再次验证以后，均无任何 bug，<strong>此时可将 <code>release</code> 分支部署到生产环境</strong>。</li><li>待上线完成后，<strong>将 <code>release</code> 分支上的代码同时合并到 <code>develop</code> 分支与 <code>master</code> 分支，并在 <code>master</code> 分支上打一个 <code>tag</code></strong>，例如 <code>v1.0.0</code>。</li><li>当生产环境发现 bug 时，我们需要<strong>从对应的 <code>tag</code> 上（例如 <code>v1.0.0</code>）拉出一条 <code>hotfix</code> 分支（例如 <code>hotfix1.0.1</code>），并在该分支上做 bug 修复</strong>。待 bug 完全修复后，需将 <code>hotfix</code> 分支上的代码同时合并到 <code>develop</code> 分支与 <code>master</code> 分支。最后，在 <code>master</code> 分支打<code>tag</code>（例如 <code>v1.0.1</code>）。</li></ol><blockquote><p><strong>对于版本号规范：</strong><br> 格式为：x.y.z，其中，x 用于有重大重构时才会升级，y 用于有新的特性发布时才会升级，z 用于修改了某个 bug 后才会升级。</p></blockquote><p><strong>使用 GIT 管理代码应该遵循以下规范：</strong></p><ol><li><p>上传内容：<strong><code>保证GIT上保存的是“干净”的代码，不得有编译后再次生成的代码</code></strong>，如 Java 字节码文件和 JSP 生成文件，也不能有 IDE 生成文件；</p></li><li><p>上传注释：<strong><code>必须加简要的注释，注释的内容应包含开发的模块名称以及功能描述</code></strong>；</p><blockquote><p>功能提交：<strong>[模块名称]功能描述</strong>，如：[用户模块]用户列表增加手机号字段显示；<br> Bug Fix：<strong>[模块名称]Bug-编号：Bug 描述</strong>，如：[用户模块]Bug-1203：用户创建保存失败已修复；</p></blockquote></li><li><p>上传质量：<strong><code>提交和合并到分支上的代码尽量保证是自己测试通过的代码</code></strong>，以免影响别的项目/同事；</p></li></ol>',6)])])}const m=o(r,[["render",a]]);export{u as __pageData,m as default};
